package pl.kmazurek.library.config

import org.springframework.beans.factory.ObjectProvider
import org.springframework.boot.info.BuildProperties
import org.springframework.stereotype.Component
import java.time.Instant

/**
 * Build metadata of the running backend, from META-INF/build-info.properties (generated by Gradle).
 * Missing when the app runs from an IDE without the Gradle build – then everything says "dev".
 */
@Component
class AppVersion(
    buildPropertiesProvider: ObjectProvider<BuildProperties>,
) {
    private val buildProperties = buildPropertiesProvider.ifAvailable

    /** Full commit SHA, or "dev" for local builds */
    val gitSha: String = buildProperties?.get("gitSha")?.takeIf { it.isNotBlank() } ?: "dev"

    /** Release tag (e.g. v0.2.0) when built from a release, otherwise null */
    val releaseTag: String? = buildProperties?.get("releaseTag")?.takeIf { it.isNotBlank() }

    val buildTime: Instant? = buildProperties?.time
}
